//! Unicode normalization / case folding and IANA time zones.
//!
//! The heavy lifting is done by `tests/data/unicode_tz_cases.matrix`, which is
//! generated by `tools/gen_unicode_tz_cases.py`: ~1500 assertions whose
//! expected values come from CPython (`unicodedata.normalize`,
//! `str.casefold`, `zoneinfo`). Running that file here means the oracle is the
//! reference implementation, not our own opinion.
//!
//! The tests below add what a data corpus cannot express: the module-level
//! helpers in `stdlib/unicode.matrix` and `stdlib/tz.matrix` (sorting, slugs,
//! day bounds, DST arithmetic), the error paths, and the strftime additions.

use spid3r_lang::diagnostics::Diagnostic;
use spid3r_lang::interpreter::Interp;
use spid3r_lang::modules;
use spid3r_lang::parser;
use spid3r_lang::semantic;
use spid3r_lang::vm::Vm;
use std::sync::Arc;

fn run_tree(src: &str, name: &str) -> Result<i32, Diagnostic> {
    let program = parser::parse_file(src, Arc::from(name))?;
    semantic::check_file(&program, true, name)?;
    let interp = Interp::new(Arc::from(name), modules::default_module_dirs());
    interp.run_program(&program)
}

fn run_vm(src: &str, name: &str) -> Result<i32, Diagnostic> {
    let program = parser::parse_file(src, Arc::from(name))?;
    semantic::check_file(&program, true, name)?;
    let dirs = modules::default_module_dirs();
    let mut vm = Vm::new(Arc::from(name), dirs);
    vm.run_program(&program)
}

fn run_both(name: &str, src: &str) {
    match run_tree(src, name) {
        Ok(0) => {}
        Ok(code) => panic!("[{}] tree engine exited {}", name, code),
        Err(e) => panic!("[{}] tree engine failed: {:?}", name, e),
    }
    match run_vm(src, name) {
        Ok(0) => {}
        Ok(code) => panic!("[{}] vm engine exited {}", name, code),
        Err(e) => panic!("[{}] vm engine failed: {:?}", name, e),
    }
}

/// The generated corpus: normalization, case folding and zone conversions
/// checked against CPython.
#[test]
fn reference_corpus_matches_cpython() {
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/unicode_tz_cases.matrix");
    let src = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {}", path.display(), e));
    run_both("unicode_tz_cases.matrix", &src);
}

#[test]
fn normalization_forms_and_equivalence() {
    run_both(
        "unicode_forms",
        r#"
import "unicode";

fn main() {
    // Canonical equivalence: two encodings, one string.
    assert(unicode_equal("é", "e" + chr(769)));
    assert(not unicode_equal("é", "e"));

    // NFC is idempotent and NFD/NFC round-trip.
    let nfd = unicode_nfd("Crème Brûlée");
    assert_eq(len(nfd), len("Crème Brûlée") + 3);
    assert_eq(unicode_nfc(nfd), "Crème Brûlée");
    assert_eq(unicode_nfc(unicode_nfc(nfd)), "Crème Brûlée");

    // Compatibility forms fold ligatures, circled digits and full-width.
    assert_eq(unicode_nfkc("ﬁ"), "fi");
    assert_eq(unicode_nfkc("①"), "1");
    assert_eq(unicode_nfkc("ＡＢ"), "AB");
    assert_eq(unicode_nfkd("㎏"), "kg");

    // is_normalized reports the truth in both directions.
    assert(unicode_is_nfc("é"));
    assert(not unicode_is_nfc("e" + chr(769)));
    assert(unicode_is_normalized("e" + chr(769), "NFD"));

    // Case folding is not lowercasing: ß folds to ss, İ to i + dot.
    assert_eq(unicode_casefold("ß"), "ss");
    assert_eq(unicode_casefold("İ"), "i" + chr(775));
    assert_eq(unicode_casefold("ΣΣ"), "σσ");
    assert(unicode_caseless_equal("STRASSE", "straße"));
    assert(unicode_caseless_equal("ΟΣ", "ος"));

    // A hole in a string literal is not affected by normalization.
    assert_eq(unicode_nfc("plain ascii"), "plain ascii");
    assert_eq(unicode_nfc(""), "");
    return 0;
}
"#,
    );
}

#[test]
fn comparison_strengths_and_sorting() {
    run_both(
        "unicode_compare",
        r#"
import "unicode";

fn main() {
    // Primary: case and accent insensitive.
    assert_eq(unicode_compare("café", "cafe", 1), 0);
    assert_eq(unicode_compare("CAFÉ", "cafe", 1), 0);
    // Secondary: case insensitive, accents matter.
    assert_eq(unicode_compare("café", "cafe", 2), 1);
    assert_eq(unicode_compare("CAFÉ", "café", 2), 0);
    // Tertiary (default): exact.
    assert_eq(unicode_compare("CAFÉ", "café"), -1);
    assert_eq(unicode_compare("a", "b"), -1);
    assert_eq(unicode_compare("b", "a"), 1);
    assert_eq(unicode_compare("a", "a"), 0);
    // Prefixes sort before their extensions.
    assert_eq(unicode_compare("ab", "abc"), -1);

    // Sorting at primary strength groups the accented and plain spellings.
    let names = ["Zoe", "émile", "alice", "Emile", "Bob"];
    let sorted = unicode_sort(names, 1);
    assert_eq(sorted[0], "alice");
    assert_eq(sorted[1], "Bob");
    assert_eq(sorted[4], "Zoe");
    // "émile" and "Emile" tie at primary strength, so the input order holds.
    assert_eq(sorted[2], "émile");
    assert_eq(sorted[3], "Emile");

    // At tertiary strength the within-level order is code points, not a
    // collation weight: "é" (U+00E9) sorts after "f" (U+0066). A real UCA
    // table would put it next to "e" - that is the documented limit, and this
    // assertion pins it so nobody "fixes" it into something locale-dependent.
    let exact = unicode_sort(["e", "é", "f"], 3);
    assert_eq(exact[0], "e");
    assert_eq(exact[1], "f");
    assert_eq(exact[2], "é");
    return 0;
}
"#,
    );
}

#[test]
fn search_keys_slugs_and_clusters() {
    run_both(
        "unicode_helpers",
        r#"
import "unicode";

fn main() {
    // Search key: case- and accent-insensitive, marks removed.
    assert_eq(unicode_search_key("Café"), "cafe");
    assert_eq(unicode_search_key("CAFÉ"), "cafe");
    assert_eq(unicode_strip_marks("e" + chr(769)), "e");
    assert_eq(unicode_strip_marks("ñ"), "n");

    // Slugs are ASCII, lowercase, dash-separated.
    assert_eq(unicode_slug("Crème Brûlée"), "creme-brulee");
    assert_eq(unicode_slug("Hello, World!"), "hello-world");
    assert_eq(unicode_slug("  spaces  and---dashes  "), "spaces-and-dashes");
    assert_eq(unicode_slug("2026"), "2026");

    // Cluster counting: a base plus its marks is one character.
    assert_eq(unicode_cluster_len("é"), 1);
    assert_eq(unicode_cluster_len("e" + chr(769)), 1);
    assert_eq(unicode_cluster_len("abc"), 3);
    assert_eq(len("e" + chr(769)), 2); // len() counts code points

    // Truncation never splits a base from its marks.
    assert_eq(unicode_truncate("e" + chr(769) + "xyz", 2), "e" + chr(769) + "x");
    assert_eq(unicode_truncate("abc", 0), "");
    assert_eq(unicode_truncate("abc", 10), "abc");
    return 0;
}
"#,
    );
}

#[test]
fn timezone_conversions_and_offsets() {
    run_both(
        "tz_basics",
        r#"
import "tz";

fn main() {
    // Offsets, abbreviations and DST flags at a fixed instant.
    assert_eq(tz_offset("Europe/Berlin", 1761000000), 7200);
    assert_eq(tz_abbr("Europe/Berlin", 1761000000), "CEST");
    assert_eq(tz_is_dst("Europe/Berlin", 1761000000), true);
    assert_eq(tz_offset("Europe/Berlin", 1700000000), 3600);
    assert_eq(tz_abbr("Europe/Berlin", 1700000000), "CET");
    assert_eq(tz_is_dst("Europe/Berlin", 1700000000), false);

    // Half-hour and 45-minute zones, and the extremes.
    assert_eq(tz_offset("Asia/Kolkata", 1761000000), 19800);
    assert_eq(tz_offset("Asia/Kathmandu", 1761000000), 20700);
    assert_eq(tz_offset("Pacific/Chatham", 1761000000), 49500);
    assert_eq(tz_offset("Pacific/Kiritimati", 1761000000), 50400);
    assert_eq(tz_offset("Pacific/Midway", 1761000000), -39600);

    // Southern hemisphere: DST in January, standard time in July.
    assert_eq(tz_is_dst("America/Santiago", 1761000000), true);
    assert_eq(tz_is_dst("America/Santiago", 1752000000), false);

    // ISO 8601 and RFC 7231.
    assert_eq(tz_iso("Europe/Berlin", 1761000000), "2025-10-21T00:40:00+02:00");
    assert_eq(tz_http_date(1761000000), "Mon, 20 Oct 2025 22:40:00 GMT");
    assert_eq(tz_describe("America/New_York", 1761000000), "Mon 2025-10-20 18:40:00 EDT -0400");

    // Wall-clock conversion between zones keeps the instant.
    let w = tz_wall_in("Asia/Shanghai", "America/New_York", 2025, 10, 21, 8, 0, 0);
    assert_eq(w["day"], 20);
    assert_eq(w["hour"], 20);
    assert_eq(w["offset"], -14400);

    // Difference between zones.
    assert_eq(tz_diff("Asia/Shanghai", "UTC", 1761000000), 28800);
    return 0;
}
"#,
    );
}

#[test]
fn timezone_dst_days_are_not_24_hours() {
    run_both(
        "tz_days",
        r#"
import "tz";

fn main() {
    // 2026-03-08 is the US spring-forward: 23 hours.
    let spring = tz_make("America/New_York", 2026, 3, 8, 12, 0, 0);
    assert_eq(tz_day_bounds("America/New_York", spring)["hours"], 23);
    // 2026-11-01 is the fall-back: 25 hours.
    let fall = tz_make("America/New_York", 2026, 11, 1, 12, 0, 0);
    assert_eq(tz_day_bounds("America/New_York", fall)["hours"], 25);
    // An ordinary day is 24.
    let normal = tz_make("America/New_York", 2026, 6, 1, 12, 0, 0);
    assert_eq(tz_day_bounds("America/New_York", normal)["hours"], 24);

    // Adding a day keeps the wall clock across the transition.
    let before = tz_make("America/New_York", 2026, 3, 7, 12, 0, 0);
    let after = tz_add_days("America/New_York", before, 1);
    assert_eq(tz_format("America/New_York", after, "%Y-%m-%d %H:%M"), "2026-03-08 12:00");
    assert_eq(after - before, 82800); // 23 hours, not 24

    // A month of daily steps lands on the same wall clock every day.
    let ts = tz_make("Europe/Berlin", 2026, 3, 25, 9, 0, 0);
    let i = 0;
    while i < 10 {
        ts = tz_add_days("Europe/Berlin", ts, 1);
        assert_eq(tz_format("Europe/Berlin", ts, "%H:%M"), "09:00");
        i += 1;
    }
    return 0;
}
"#,
    );
}

#[test]
fn timezone_registry_and_errors() {
    run_both(
        "tz_registry",
        r#"
import "tz";

fn main() {
    // Every advertised name must resolve - links included.
    let names = tz_names();
    assert(len(names) > 500);
    let unresolved = 0;
    for n in names {
        if not tz_info(n, 0).is_ok() {
            unresolved += 1;
        }
    }
    assert_eq(unresolved, 0);

    // A link and its target are the same zone.
    assert_eq(tz_offset("Asia/Calcutta", 1761000000), tz_offset("Asia/Kolkata", 1761000000));
    assert_eq(tz_iso("Asia/Calcutta", 1761000000), tz_iso("Asia/Kolkata", 1761000000));

    // Prefix filtering.
    let asia = tz_zones("Asia/");
    assert(len(asia) > 50);
    for n in asia {
        assert(n.starts_with("Asia/"));
    }

    // Unknown zones are an error, not a panic or a silent UTC fallback.
    assert(tz_info("Mars/Olympus_Mons", 0).is_err());
    assert(tz_info("Mars/Olympus_Mons", 0).unwrap_err().contains("unknown time zone"));
    assert_eq(tz_valid("Asia/Tokyo"), true);
    assert_eq(tz_valid("Mars/Olympus_Mons"), false);

    // Historical offsets are real: 1900 is LMT, not the modern zone offset.
    assert(tz_offset("Asia/Shanghai", -2208988800) != tz_offset("Asia/Shanghai", 1761000000));
    // And the data version is reported.
    assert(len(tz_data_version()) > 0);
    return 0;
}
"#,
    );
}

#[test]
fn strftime_offset_and_name_specifiers() {
    run_both(
        "strftime",
        r#"
import "tz";

fn main() {
    // format_datetime is UTC: %z is +0000 and %Z is UTC.
    assert_eq(format_datetime(0, "%Y-%m-%dT%H:%M:%S%z"), "1970-01-01T00:00:00+0000");
    assert_eq(format_datetime(0, "%Z"), "UTC");

    // The new name and calendar specifiers.
    assert_eq(format_datetime(0, "%a %A %b %B"), "Thu Thursday Jan January");
    assert_eq(format_datetime(0, "%j"), "001");
    assert_eq(format_datetime(0, "%e"), " 1");
    assert_eq(format_datetime(0, "%I %p"), "12 AM");
    assert_eq(format_datetime(43200, "%I %p"), "12 PM");
    assert_eq(format_datetime(0, "%u"), "4");
    assert_eq(format_datetime(1761000000, "%F %T"), "2025-10-20 22:40:00");

    // A zone-aware format reports the zone's own offset and abbreviation.
    assert_eq(tz_format("Asia/Kolkata", 1761000000, "%z"), "+0530");
    assert_eq(tz_format("Asia/Kathmandu", 1761000000, "%z"), "+0545");
    assert_eq(tz_format("America/St_Johns", 1761000000, "%z"), "-0230");
    assert_eq(tz_format("Pacific/Kiritimati", 1761000000, "%z"), "+1400");

    // A historical LMT offset has seconds, and dropping them would shift the
    // timestamp by up to a minute, so %z keeps them.
    assert_eq(tz_format("Africa/Addis_Ababa", -1946168836, "%z"), "+0230");
    return 0;
}
"#,
    );
}

#[test]
fn normalization_rejects_bad_arguments() {
    run_both(
        "unicode_errors",
        r#"
import "unicode";

fn caught(f) {
    try {
        f();
        return "";
    } catch(e) {
        return string(e);
    }
}

fn main() {
    let msg = caught(fn() { return unicode_normalize("x", "NFCX"); });
    assert(msg.contains("unknown normalization form"));

    let msg2 = caught(fn() { return unicode_compare("a", "b", 4); });
    assert(msg2.contains("strength must be"));

    let msg3 = caught(fn() { return unicode_combining_class("ab"); });
    assert(msg3.contains("exactly one character"));

    // Lowercase form names are accepted.
    assert_eq(unicode_normalize("e" + chr(769), "nfc"), "é");
    return 0;
}
"#,
    );
}
